MOTIF_NAME = 'king_safety_pawn_storm'
MOTIF_DESCRIPTION = 'The side to move has more pawns on the wing where the opponent king is located than the opponent has on the side-to-move king wing, indicating a pawn storm advantage.'
def motif(fen: str) -> bool:
    import chess
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm

    opp_king_sq = board.king(opp)
    if opp_king_sq is None:
        return False
    stm_king_sq = board.king(stm)
    if stm_king_sq is None:
        return False

    opp_kf = chess.square_file(opp_king_sq)
    stm_kf = chess.square_file(stm_king_sq)

    def wing_pawns(color, king_file):
        count = 0
        for sq in board.pieces(chess.PAWN, color):
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            if king_file <= 3:
                if f <= 3:
                    count += 1
            else:
                if f >= 4:
                    count += 1
        return count

    stm_storm = wing_pawns(stm, opp_kf)
    opp_storm = wing_pawns(opp, stm_kf)

    return stm_storm > opp_storm

MOTIF_NAME = 'knight_attacking_king_zone'
MOTIF_DESCRIPTION = 'The side to move has a knight attacking squares near the opponent king while the opponent has no equivalent attack.'
def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm

    opp_king_sq = board.king(opp)
    if opp_king_sq is None:
        return False

    king_zone = []
    for sq in chess.SQUARES:
        if chess.square_distance(opp_king_sq, sq) <= 2:
            king_zone.append(sq)

    stm_knights = board.pieces(chess.KNIGHT, stm)
    stm_attacks = 0
    for knight_sq in stm_knights:
        for target in chess.SQUARES:
            if target in king_zone:
                if target in board.attacks(knight_sq):
                    piece = board.piece_at(target)
                    if piece is None or piece.color == opp:
                        stm_attacks += 1

    stm_king_sq = board.king(stm)
    if stm_king_sq is None:
        return False
    stm_king_zone = []
    for sq in chess.SQUARES:
        if chess.square_distance(stm_king_sq, sq) <= 2:
            stm_king_zone.append(sq)

    opp_knights = board.pieces(chess.KNIGHT, opp)
    opp_attacks = 0
    for knight_sq in opp_knights:
        for target in chess.SQUARES:
            if target in stm_king_zone:
                if target in board.attacks(knight_sq):
                    piece = board.piece_at(target)
                    if piece is None or piece.color == stm:
                        opp_attacks += 1

    return stm_attacks > opp_attacks

MOTIF_NAME = 'restricted_opponent_pieces'
MOTIF_DESCRIPTION = 'The side to move has more opponent pieces (queen, rooks, bishops, knights) on ranks 1-2 from their perspective than the opponent has restricted pieces on the side-to-move side, indicating a space advantage cramping the opponent.'
def motif(fen: str) -> bool:
    import chess
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm

    # Count opponent pieces restricted to their home ranks (1-2 from their own side)
    stm_restricted = 0
    opp_restricted = 0

    for sq in chess.SQUARES:
        piece = board.piece_at(sq)
        if piece is None:
            continue
        if piece.piece_type == chess.PAWN or piece.piece_type == chess.KING:
            continue

        rank = chess.square_rank(sq)
        if piece.color == opp:
            # From opponent's perspective, ranks 0-1 are home ranks
            if piece.color == chess.WHITE:
                if rank <= 1:
                    stm_restricted += 1
            else:
                if rank >= 6:
                    stm_restricted += 1
        elif piece.color == stm:
            if piece.color == chess.WHITE:
                if rank <= 1:
                    opp_restricted += 1
            else:
                if rank >= 6:
                    opp_restricted += 1

    return stm_restricted > opp_restricted and stm_restricted >= 1

MOTIF_NAME = 'centralized_active_piece_advantage'
MOTIF_DESCRIPTION = 'The side to move has a knight or bishop on or beyond the fourth rank (from its perspective) that attacks at least one central square, while the opponent has no such active minor piece.'
def motif(fen: str) -> bool:
    import chess
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm

    central_squares = {chess.D4, chess.E4, chess.D5, chess.E5}

    def has_active_minor(color):
        for piece_type in (chess.KNIGHT, chess.BISHOP):
            for sq in board.pieces(piece_type, color):
                rank = chess.square_rank(sq)
                if (color == chess.WHITE and rank >= 3) or (color == chess.BLACK and rank <= 4):
                    if any(t in central_squares for t in board.attacks(sq)):
                        return True
        return False

    stm_has = has_active_minor(stm)
    opp_has = has_active_minor(opp)
    return stm_has and not opp_has

MOTIF_NAME = 'safe_pawn_break_threat'
MOTIF_DESCRIPTION = 'The side to move threatens a pawn break that would open lines against the opponent king, while the opponent has no comparable threat.'
def motif(fen: str) -> bool:
    import chess
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm

    # Find opponent king
    opp_king_sq = board.king(opp)
    if opp_king_sq is None:
        return False
    opp_kf = chess.square_file(opp_king_sq)
    opp_kr = chess.square_rank(opp_king_sq)

    # Define king zone for opponent (king square and adjacent squares)
    king_zone = set()
    for df in (-1, 0, 1):
        for dr in (-1, 0, 1):
            f = opp_kf + df
            r = opp_kr + dr
            if 0 <= f <= 7 and 0 <= r <= 7:
                king_zone.add(chess.square(f, r))

    # Helper: check if a pawn advance opens a line (file, rank, diagonal) toward king zone
    def pawn_advances_toward_king(pawn_sq, color):
        pf = chess.square_file(pawn_sq)
        pr = chess.square_rank(pawn_sq)
        direction = 1 if color == chess.WHITE else -1
        # One square advance
        target_sq = chess.square(pf, pr + direction)
        if 0 <= pr + direction <= 7:
            # Remove pawn temporarily to see what lines open
            board_copy = board.copy()
            board_copy.remove_piece_at(pawn_sq)
            # Check if any piece attacks king zone squares through the vacated file/diagonal
            for sq in king_zone:
                attackers = board_copy.attackers(color, sq)
                for att_sq in attackers:
                    piece = board_copy.piece_at(att_sq)
                    if piece and piece.piece_type in (chess.QUEEN, chess.ROOK, chess.BISHOP):
                        # Check line of sight
                        if board_copy.attacks(att_sq) & chess.SquareSet(1 << sq):
                            # Make sure the pawn move doesn't just expose the king
                            stm_king_sq = board.king(color)
                            if stm_king_sq is None or not board_copy.is_attacked_by(opp, stm_king_sq):
                                return True
        # Two square advance for pawns on starting rank
        start_rank = 1 if color == chess.WHITE else 6
        if pr == start_rank:
            target_sq = chess.square(pf, pr + 2*direction)
            if 0 <= pr + 2*direction <= 7:
                board_copy = board.copy()
                board_copy.remove_piece_at(pawn_sq)
                for sq in king_zone:
                    attackers = board_copy.attackers(color, sq)
                    for att_sq in attackers:
                        piece = board_copy.piece_at(att_sq)
                        if piece and piece.piece_type in (chess.QUEEN, chess.ROOK, chess.BISHOP):
                            if board_copy.attacks(att_sq) & chess.SquareSet(1 << sq):
                                stm_king_sq = board.king(color)
                                if stm_king_sq is None or not board_copy.is_attacked_by(opp, stm_king_sq):
                                    return True
        return False

    # Check if stm has a pawn break toward opponent king
    stm_has_break = False
    for pawn_sq in board.pieces(chess.PAWN, stm):
        if pawn_advances_toward_king(pawn_sq, stm):
            stm_has_break = True
            break

    if not stm_has_break:
        return False

    # Check if opponent has a pawn break toward stm king
    stm_king_sq = board.king(stm)
    if stm_king_sq is None:
        return False
    stm_kf = chess.square_file(stm_king_sq)
    stm_kr = chess.square_rank(stm_king_sq)
    stm_king_zone = set()
    for df in (-1, 0, 1):
        for dr in (-1, 0, 1):
            f = stm_kf + df
            r = stm_kr + dr
            if 0 <= f <= 7 and 0 <= r <= 7:
                stm_king_zone.add(chess.square(f, r))

    # Temporarily override king_zone for opponent check
    orig_king_zone = king_zone
    # Use a local function to check opp breaks
    def opp_pawn_advances_toward_king(pawn_sq, color):
        pf = chess.square_file(pawn_sq)
        pr = chess.square_rank(pawn_sq)
        direction = 1 if color == chess.WHITE else -1
        target_sq = chess.square(pf, pr + direction)
        if 0 <= pr + direction <= 7:
            board_copy = board.copy()
            board_copy.remove_piece_at(pawn_sq)
            for sq in stm_king_zone:
                attackers = board_copy.attackers(color, sq)
                for att_sq in attackers:
                    piece = board_copy.piece_at(att_sq)
                    if piece and piece.piece_type in (chess.QUEEN, chess.ROOK, chess.BISHOP):
                        if board_copy.attacks(att_sq) & chess.SquareSet(1 << sq):
                            opp_king_sq2 = board.king(color)
                            if opp_king_sq2 is None or not board_copy.is_attacked_by(stm, opp_king_sq2):
                                return True
        start_rank = 1 if color == chess.WHITE else 6
        if pr == start_rank:
            target_sq = chess.square(pf, pr + 2*direction)
            if 0 <= pr + 2*direction <= 7:
                board_copy = board.copy()
                board_copy.remove_piece_at(pawn_sq)
                for sq in stm_king_zone:
                    attackers = board_copy.attackers(color, sq)
                    for att_sq in attackers:
                        piece = board_copy.piece_at(att_sq)
                        if piece and piece.piece_type in (chess.QUEEN, chess.ROOK, chess.BISHOP):
                            if board_copy.attacks(att_sq) & chess.SquareSet(1 << sq):
                                opp_king_sq2 = board.king(color)
                                if opp_king_sq2 is None or not board_copy.is_attacked_by(stm, opp_king_sq2):
                                    return True
        return False

    for pawn_sq in board.pieces(chess.PAWN, opp):
        if opp_pawn_advances_toward_king(pawn_sq, opp):
            return False

    return True

MOTIF_NAME = 'bishop_attacking_king_zone'
MOTIF_DESCRIPTION = 'The side to move has a bishop attacking squares adjacent to the opponent king while the opponent has no such bishop attack on the side-to-move king.'
def motif(fen: str) -> bool:
    import chess
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm

    opp_king_sq = board.king(opp)
    if opp_king_sq is None:
        return False
    stm_king_sq = board.king(stm)
    if stm_king_sq is None:
        return False

    king_zone = []
    kf = chess.square_file(opp_king_sq)
    kr = chess.square_rank(opp_king_sq)
    for df in (-1, 0, 1):
        for dr in (-1, 0, 1):
            if df == 0 and dr == 0:
                continue
            nf = kf + df
            nr = kr + dr
            if 0 <= nf <= 7 and 0 <= nr <= 7:
                king_zone.append(chess.square(nf, nr))

    stm_bishops = board.pieces(chess.BISHOP, stm)
    stm_attacks_zone = False
    for bsq in stm_bishops:
        attacks = board.attacks(bsq)
        for zsq in king_zone:
            if zsq in attacks:
                stm_attacks_zone = True
                break
        if stm_attacks_zone:
            break

    if not stm_attacks_zone:
        return False

    stm_king_zone = []
    kf2 = chess.square_file(stm_king_sq)
    kr2 = chess.square_rank(stm_king_sq)
    for df in (-1, 0, 1):
        for dr in (-1, 0, 1):
            if df == 0 and dr == 0:
                continue
            nf = kf2 + df
            nr = kr2 + dr
            if 0 <= nf <= 7 and 0 <= nr <= 7:
                stm_king_zone.append(chess.square(nf, nr))

    opp_bishops = board.pieces(chess.BISHOP, opp)
    opp_attacks_zone = False
    for bsq in opp_bishops:
        attacks = board.attacks(bsq)
        for zsq in stm_king_zone:
            if zsq in attacks:
                opp_attacks_zone = True
                break
        if opp_attacks_zone:
            break

    return not opp_attacks_zone

MOTIF_NAME = 'knight_outpost_attacking_center'
MOTIF_DESCRIPTION = 'The side to move has a knight on a protected outpost square (immune to opponent pawns, defended by a friendly pawn) that attacks at least one central square (d4,e4,d5,e5), while the opponent has no such knight.'
def motif(fen: str) -> bool:
    import chess
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm

    central_squares = [chess.E4, chess.D4, chess.E5, chess.D5]

    def is_protected_outpost(sq, color):
        if board.piece_at(sq) is None:
            return False
        piece = board.piece_at(sq)
        if piece.piece_type != chess.KNIGHT or piece.color != color:
            return False
        # Not attackable by opponent pawns
        opp_pawn_attacks = board.pieces(chess.PAWN, not color)
        for psq in opp_pawn_attacks:
            attacks = board.attacks(psq)
            if sq in attacks:
                return False
        # Defended by a friendly pawn
        friendly_pawns = board.pieces(chess.PAWN, color)
        for psq in friendly_pawns:
            attacks = board.attacks(psq)
            if sq in attacks:
                return True
        return False

    def attacks_center(sq):
        kn_attacks = board.attacks(sq)
        for csq in central_squares:
            if csq in kn_attacks:
                return True
        return False

    stm_has = False
    for sq in board.pieces(chess.KNIGHT, stm):
        if is_protected_outpost(sq, stm) and attacks_center(sq):
            stm_has = True
            break

    if not stm_has:
        return False

    opp_has = False
    for sq in board.pieces(chess.KNIGHT, opp):
        if is_protected_outpost(sq, opp) and attacks_center(sq):
            opp_has = True
            break

    return not opp_has

MOTIF_NAME = 'knight_vs_bishop_control_imbalance'
MOTIF_DESCRIPTION = 'The side to move has more knights on outpost squares (protected by pawns, not attackable by opponent pawns) than the opponent has bishops on open diagonals (diagonals with no friendly pawns blocking), indicating a positional piece-type advantage.'
def motif(fen: str) -> bool:
    import chess
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm

    def is_outpost(sq, color):
        # Knight on a square protected by a friendly pawn and not attackable by opponent pawns
        if not board.attackers(color, sq):
            return False
        if board.attackers(opp, sq) & board.pieces(chess.PAWN, opp):
            return False
        # Must be protected by a friendly pawn
        pawn_attackers = board.attackers(color, sq) & board.pieces(chess.PAWN, color)
        return bool(pawn_attackers)

    def has_open_diagonal(sq, color):
        # Bishop on a diagonal with no friendly pawns on squares of same color
        f, r = chess.square_file(sq), chess.square_rank(sq)
        sq_color = (f + r) % 2
        for osq in chess.SQUARES:
            of, or_ = chess.square_file(osq), chess.square_rank(osq)
            if (of + or_) % 2 == sq_color:
                p = board.piece_at(osq)
                if p and p.piece_type == chess.PAWN and p.color == color:
                    if of != f:  # Same color square, different file means same diagonal complex
                        # Check if on same diagonal
                        if abs(of - f) == abs(or_ - r) and (of != f):
                            return False
        return True

    stm_knights = board.pieces(chess.KNIGHT, stm)
    opp_bishops = board.pieces(chess.BISHOP, opp)

    stm_outposts = 0
    for sq in stm_knights:
        if is_outpost(sq, stm):
            stm_outposts += 1

    opp_open_bishops = 0
    for sq in opp_bishops:
        if has_open_diagonal(sq, opp):
            opp_open_bishops += 1

    if stm_outposts == 0:
        return False
    return stm_outposts > opp_open_bishops

MOTIF_NAME = 'passed_pawn_protected'
MOTIF_DESCRIPTION = 'The side to move has a passed pawn that is defended by a friendly pawn, while the opponent has no such supported passed pawn.'
def motif(fen: str) -> bool:
    import chess
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm

    # Determine which ranks are the promotion direction for stm
    if stm == chess.WHITE:
        stm_pawn_dir = 1
        stm_promotion_rank = 7
        opp_pawn_dir = -1
        opp_promotion_rank = 0
    else:
        stm_pawn_dir = -1
        stm_promotion_rank = 0
        opp_pawn_dir = 1
        opp_promotion_rank = 7

    def is_passed(color, sq):
        """Check if the pawn on sq is a passed pawn (no opponent pawns blocking its path)."""
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        if color == chess.WHITE:
            # Check ranks from r+1 to 7 on files f-1, f, f+1
            for check_file in (f-1, f, f+1):
                if 0 <= check_file <= 7:
                    for check_rank in range(r + 1, 8):
                        p = board.piece_at(chess.square(check_file, check_rank))
                        if p and p.piece_type == chess.PAWN and p.color != color:
                            return False
        else:
            for check_file in (f-1, f, f+1):
                if 0 <= check_file <= 7:
                    for check_rank in range(r - 1, -1, -1):
                        p = board.piece_at(chess.square(check_file, check_rank))
                        if p and p.piece_type == chess.PAWN and p.color != color:
                            return False
        return True

    def supported_by_friendly_pawn(color, sq):
        """Check if any friendly pawn defends this square directly."""
        f = chess.square_file(sq)
        r = chess.square_rank(sq)
        if color == chess.WHITE:
            # Pawns defend from one rank below, diagonally
            if r > 0:
                for df in (-1, 1):
                    cf = f + df
                    if 0 <= cf <= 7:
                        defender = board.piece_at(chess.square(cf, r - 1))
                        if defender and defender.piece_type == chess.PAWN and defender.color == color:
                            return True
        else:
            if r < 7:
                for df in (-1, 1):
                    cf = f + df
                    if 0 <= cf <= 7:
                        defender = board.piece_at(chess.square(cf, r + 1))
                        if defender and defender.piece_type == chess.PAWN and defender.color == color:
                            return True
        return False

    stm_passed = 0
    opp_passed = 0

    for sq in chess.SQUARES:
        p = board.piece_at(sq)
        if not p or p.piece_type != chess.PAWN:
            continue
        if p.color == stm:
            if is_passed(stm, sq) and supported_by_friendly_pawn(stm, sq):
                stm_passed += 1
        else:
            if is_passed(opp, sq) and supported_by_friendly_pawn(opp, sq):
                opp_passed += 1

    return stm_passed > opp_passed

MOTIF_NAME = 'knight_on_outpost'
MOTIF_DESCRIPTION = 'The side to move has a knight on a square that cannot be attacked by opponent pawns and is protected by a friendly pawn.'
def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm

    # Precompute opponent pawn squares
    opp_pawn_squares = board.pieces(chess.PAWN, opp)

    # Precompute stm pawn squares
    stm_pawn_squares = board.pieces(chess.PAWN, stm)

    # Helper to check if a square is attacked by any opponent pawn
    def square_attacked_by_opp_pawn(sq):
        file = chess.square_file(sq)
        rank = chess.square_rank(sq)
        if stm == chess.WHITE:
            # Black pawns attack from rank+1
            if rank <= 6:
                attack_rank = rank + 1
                if file > 0:
                    if chess.square(file - 1, attack_rank) in opp_pawn_squares:
                        return True
                if file < 7:
                    if chess.square(file + 1, attack_rank) in opp_pawn_squares:
                        return True
        else:
            # White pawns attack from rank-1
            if rank >= 1:
                attack_rank = rank - 1
                if file > 0:
                    if chess.square(file - 1, attack_rank) in opp_pawn_squares:
                        return True
                if file < 7:
                    if chess.square(file + 1, attack_rank) in opp_pawn_squares:
                        return True
        return False

    # Check each stm knight
    for knight_sq in board.pieces(chess.KNIGHT, stm):
        if square_attacked_by_opp_pawn(knight_sq):
            continue
        # Check if defended by at least one stm pawn
        file = chess.square_file(knight_sq)
        rank = chess.square_rank(knight_sq)
        defended = False
        if stm == chess.WHITE:
            # White pawns defend from rank-1
            if rank >= 1:
                def_rank = rank - 1
                if file > 0 and chess.square(file - 1, def_rank) in stm_pawn_squares:
                    defended = True
                if file < 7 and chess.square(file + 1, def_rank) in stm_pawn_squares:
                    defended = True
        else:
            # Black pawns defend from rank+1
            if rank <= 6:
                def_rank = rank + 1
                if file > 0 and chess.square(file - 1, def_rank) in stm_pawn_squares:
                    defended = True
                if file < 7 and chess.square(file + 1, def_rank) in stm_pawn_squares:
                    defended = True
        if defended:
            # Additional condition: knight is on opponent's half or center
            if stm == chess.WHITE and rank >= 4:
                return True
            if stm == chess.BLACK and rank <= 3:
                return True
            # Also consider knights on the 4th rank for both colors
            if rank == 3 or rank == 4:
                return True
    return False

MOTIF_NAME = 'unstoppable_passed_pawn'
MOTIF_DESCRIPTION = 'The side to move has a passed pawn that cannot be caught by the opponent.'
def motif(fen: str) -> bool:
    import chess
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm

    # Find all pawns for side to move
    stm_pawns = board.pieces(chess.PAWN, stm)
    if not stm_pawns:
        return False

    opp_king_sq = board.king(opp)
    if opp_king_sq is None:
        return False

    stm_king_sq = board.king(stm)

    # Get opponent pawns for passed-pawn detection
    opp_pawns = board.pieces(chess.PAWN, opp)

    for pawn_sq in stm_pawns:
        file = chess.square_file(pawn_sq)
        rank = chess.square_rank(pawn_sq)

        # Passed pawn check: no opponent pawns on same or adjacent files ahead
        passed = True
        if stm == chess.WHITE:
            # White pawns go from rank 1 to 7
            for f in (file-1, file, file+1):
                if f < 0 or f > 7:
                    continue
                for r in range(rank+1, 8):
                    sq = chess.square(f, r)
                    if sq in opp_pawns:
                        passed = False
                        break
                if not passed:
                    break
        else:
            # Black pawns go from rank 6 down to 0
            for f in (file-1, file, file+1):
                if f < 0 or f > 7:
                    continue
                for r in range(rank-1, -1, -1):
                    sq = chess.square(f, r)
                    if sq in opp_pawns:
                        passed = False
                        break
                if not passed:
                    break

        if not passed:
            continue

        # Now check if the opponent king can catch this pawn
        promo_rank = 7 if stm == chess.WHITE else 0
        if stm == chess.WHITE:
            dist_to_promo = 7 - rank
        else:
            dist_to_promo = rank - 0

        # squares the pawn needs to advance through
        pawn_path = []
        if stm == chess.WHITE:
            for r in range(rank, 8):
                pawn_path.append(chess.square(file, r))
        else:
            for r in range(rank, -1, -1):
                pawn_path.append(chess.square(file, r))

        # Minimal king distance to any square on the pawn's path
        min_king_dist = min(chess.square_distance(opp_king_sq, sq) for sq in pawn_path)

        # Can opponent king intercept? Factor in whose turn it is (opp moves right after)
        # If it's stm's turn, pawn has a head start
        # Pawn needs dist_to_promo moves. King needs min_king_dist moves.
        # But king can't move through pieces. Simplified: if king distance > pawn distance + 1, unstoppable
        if min_king_dist > dist_to_promo + 1:
            return True

        # Check if own king can block the opponent king from getting to the pawn
        if stm_king_sq is not None:
            # own king is close enough to shield
            if chess.square_distance(stm_king_sq, pawn_sq) <= 3 and chess.square_distance(stm_king_sq, opp_king_sq) <= 2:
                # own king can potentially block
                pass # not strong enough on its own, continue to next checks

        # King can't reach any stop square of the pawn
        if stm == chess.WHITE:
            stops = []
            if rank + 1 <= 7:
                stops.append(chess.square(file, rank+1))
            if rank == 1:  # double push possible?
                if board.piece_at(chess.square(file, rank+1)) is None and board.piece_at(chess.square(file, rank+2)) is None:
                    stops.append(chess.square(file, rank+2))
            if rank + 2 <= 7:
                stops.append(chess.square(file, rank+2))
        else:
            stops = []
            if rank - 1 >= 0:
                stops.append(chess.square(file, rank-1))
            if rank == 6:
                if board.piece_at(chess.square(file, rank-1)) is None and board.piece_at(chess.square(file, rank-2)) is None:
                    stops.append(chess.square(file, rank-2))
            if rank - 2 >= 0:
                stops.append(chess.square(file, rank-2))

        if stops and all(chess.square_distance(opp_king_sq, s) > 1 for s in stops):
            # King is too far to immediately block; check further
            # Recalculate properly: king needs to reach some square on the pawn's forward path
            # before the pawn promotes. If distance is strictly greater, it's unstoppable.
            if min_king_dist > dist_to_promo:
                return True

    return False

MOTIF_NAME = 'rook_behind_passed_pawn'
MOTIF_DESCRIPTION = 'The side to move has a rook behind its own passed pawn while the opponent has no rook behind their own passed pawn.'
def motif(fen: str) -> bool:
    import chess
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm

    def has_passed_pawn(color):
        pawns = board.pieces(chess.PAWN, color)
        opp_pawns = board.pieces(chess.PAWN, not color)
        passed = []
        for sq in pawns:
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            passed_flag = True
            for opp_sq in opp_pawns:
                of = chess.square_file(opp_sq)
                if abs(of - f) <= 1:
                    or_ = chess.square_rank(opp_sq)
                    if (color == chess.WHITE and or_ > r) or (color == chess.BLACK and or_ < r):
                        passed_flag = False
                        break
            if passed_flag:
                passed.append(sq)
        return passed

    def rook_behind_own_passed(color):
        passed = has_passed_pawn(color)
        rooks = board.pieces(chess.ROOK, color)
        for rsq in rooks:
            rf = chess.square_file(rsq)
            rr = chess.square_rank(rsq)
            for psq in passed:
                if chess.square_file(psq) != rf:
                    continue
                pr = chess.square_rank(psq)
                if color == chess.WHITE:
                    if rr < pr:
                        return True
                else:
                    if rr > pr:
                        return True
        return False

    stm_has = rook_behind_own_passed(stm)
    opp_has = rook_behind_own_passed(opp)
    return stm_has and not opp_has

MOTIF_NAME = 'piece_attacking_king_defended_target'
MOTIF_DESCRIPTION = 'The side to move has a piece attacking an opponent piece that is only defended by the opponent king, while the opponent has no such attack, indicating a tactical vulnerability.'
def motif(fen: str) -> bool:
    import chess
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm

    opp_king = board.king(opp)
    if opp_king is None:
        return False

    def has_king_only_defended_target(attacking_color, defending_color, def_king):
        for sq in board.pieces(chess.PAWN, defending_color):
            attackers = board.attackers(attacking_color, sq)
            defenders = board.attackers(defending_color, sq)
            if attackers and len(defenders) == 1 and def_king in defenders:
                return True
        for pt in (chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN):
            for sq in board.pieces(pt, defending_color):
                attackers = board.attackers(attacking_color, sq)
                defenders = board.attackers(defending_color, sq)
                if attackers and len(defenders) == 1 and def_king in defenders:
                    return True
        return False

    stm_has = has_king_only_defended_target(stm, opp, opp_king)
    if not stm_has:
        return False

    stm_king = board.king(stm)
    if stm_king is None:
        return False

    opp_has = has_king_only_defended_target(opp, stm, stm_king)
    return not opp_has
